CREATE TABLE IF NOT EXISTS workspace_schema_migrations (
  id INTEGER PRIMARY KEY,
  name TEXT NOT NULL UNIQUE,
  checksum TEXT NOT NULL,
  applied_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  applied_by_version TEXT NOT NULL,
  applied_by_commit TEXT
);

CREATE TABLE IF NOT EXISTS workspace_audit (
  id INTEGER PRIMARY KEY,
  event_type TEXT NOT NULL CHECK(length(trim(event_type)) > 0),
  entity_type TEXT NOT NULL CHECK(length(trim(entity_type)) > 0),
  entity_id TEXT,
  actor TEXT NOT NULL CHECK(length(trim(actor)) > 0),
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
);

CREATE INDEX IF NOT EXISTS idx_workspace_audit_entity
  ON workspace_audit(entity_type, entity_id, id DESC);

CREATE TRIGGER IF NOT EXISTS workspace_schema_migrations_no_update
BEFORE UPDATE ON workspace_schema_migrations
BEGIN
  SELECT RAISE(ABORT, 'workspace migration history is append-only');
END;

CREATE TRIGGER IF NOT EXISTS workspace_schema_migrations_no_delete
BEFORE DELETE ON workspace_schema_migrations
BEGIN
  SELECT RAISE(ABORT, 'workspace migration history is append-only');
END;

CREATE TRIGGER IF NOT EXISTS workspace_audit_no_update
BEFORE UPDATE ON workspace_audit
BEGIN
  SELECT RAISE(ABORT, 'workspace audit is append-only');
END;

CREATE TRIGGER IF NOT EXISTS workspace_audit_no_delete
BEFORE DELETE ON workspace_audit
BEGIN
  SELECT RAISE(ABORT, 'workspace audit is append-only');
END;
